// ⓪ ENTRADA · cadena · fechas especiales · SOLO corre si el cliente declaró este tipo de fecha (la lista vacía no investiga NADA)
// Paga un agente: `seco` explícito o se DETIENE antes de gastar. El simulacro (páginas y respuesta enlatadas) SOLO existe en seco.
const e = $input.first().json || {}
if (typeof e.campana_id !== 'string' || e.campana_id.trim() === '') throw new Error('CADENA_SIN_CAMPANA · falta campana_id · se DETIENE y no escribe nada')
if (typeof e.seco !== 'boolean') throw new Error('CADENA_SECO_AUSENTE · el pedido debe traer seco explícito (true o false) · se DETIENE antes de gastar')
for (const k of ['pais', 'tipo', 'ambito']) if (typeof e[k] !== 'string' || e[k].trim() === '') throw new Error('CADENA_FECHAS_SIN_' + k.toUpperCase() + ' · falta ' + k)
if (!Number.isInteger(e.anio)) throw new Error('CADENA_FECHAS_SIN_ANIO · falta anio (entero)')
const simulacro = e.seco === true && e.simulacro && typeof e.simulacro === 'object' ? e.simulacro : null
return [{ json: { paso: 'fechas', campana_id: e.campana_id, seco: e.seco, pais: e.pais, tipo: e.tipo, ambito: e.ambito, anio: e.anio, simulacro, workflow_id: String($workflow.id), workflow_execution_id: String($execution.id) } }]

// ① ¿QUÉ DIJO `cobertura`? · ya verificada o sin fuente = FIN (no se repite el gasto) · investigar = una fila por dominio permitido (la lista sale de cadena_config, vacía por defecto)
const s = $('⓪ Entrada').last().json
const r = $input.first().json || {}
const status = Number(r.statusCode)
const b = r.body && typeof r.body === 'object' ? r.body : {}
if (status !== 200) throw new Error('CADENA_COBERTURA_' + String(b.code || b.error || status) + ' · ' + String(b.detalle || b.detail || 'sin detalle'))
if (b.estado === 'ya_verificada' || b.estado === 'sin_fuente') return [{ json: { ...s, fin: true, resultado: b.estado, detalle: b } }]
if (b.estado === 'investigar' && Array.isArray(b.dominios) && b.dominios.length > 0) return b.dominios.map((d) => ({ json: { ...s, fin: false, dominio: String(d), intento: b.intento } }))
throw new Error('CADENA_COBERTURA_NO_ENTENDIDA · ' + JSON.stringify(b).slice(0, 300))

// ② PÁGINAS SIMULADAS · SOLO en seco: las páginas enlatadas del ensayo (cero descargas)
const s = $input.first().json
const sim = s.simulacro || {}
return [{ json: { ...s, paginas: Array.isArray(sim.paginas) ? sim.paginas : [] } }]

// ② JUNTAR LAS PÁGINAS · el CÓDIGO descargó las páginas (nodo HTTP); aquí solo se limpian a texto. El agente NUNCA navega: lee lo que el código bajó.
const filas = $('① ¿Qué dijo?').all()
const respuestas = $input.all()
const aTexto = (html) => String(html || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/\s+/g, ' ').trim()
const paginas = []
respuestas.forEach((r, i) => {
  const j = r.json || {}
  const url = filas[i] && filas[i].json ? filas[i].json.dominio : null
  const cuerpo = typeof j.body === 'string' ? j.body : ''
  if (url && Number(j.statusCode) >= 200 && Number(j.statusCode) < 300 && cuerpo) paginas.push({ url, texto: aTexto(cuerpo).slice(0, 60000) })
})
const s = filas[0].json
return [{ json: { ...s, paginas } }]

// ③ ARMAR `preparar` de las fechas · las páginas ya descargadas viajan en el pedido; la ruta arma el cuerpo completo del agente
const s = $input.first().json
const pedido = { accion: 'preparar', campana_id: s.campana_id, seco: s.seco, pais: s.pais, tipo: s.tipo, ambito: s.ambito, anio: s.anio, paginas: s.paginas || [], workflow_id: s.workflow_id, workflow_execution_id: s.workflow_execution_id }
return [{ json: { ...s, pedido } }]

// ③ ¿QUÉ DIJO `preparar`? · lista para llamar · ya hecha · sin fuente (el tipo queda sin fuente y la campaña SIGUE) · lo demás falla ruidoso antes de gastar
const s = $('③ Armar preparar').last().json
const r = $input.first().json || {}
const status = Number(r.statusCode)
const b = r.body && typeof r.body === 'object' ? r.body : {}
const base = { ...s }
delete base.pedido; delete base.paginas
if (status === 200 && b.run_sdk) return [{ json: { ...base, fin: false, corrida_id: b.corrida_id, headers: b.headers || {}, run_sdk: b.run_sdk } }]
if (status === 200 && (b.ya_hecha === true || b.estado === 'sin_fuente')) return [{ json: { ...base, fin: true, resultado: b.ya_hecha ? 'ya_hecha' : 'sin_fuente', detalle: b } }]
throw new Error('CADENA_FECHAS_PREPARAR_' + String(b.code || b.error || status) + ' · ' + String(b.detalle || b.detail || 'sin detalle') + ' · no se llamó a ningún agente')

// ④ SIMULACRO · SOLO en seco: la respuesta enlatada del agente (cero llamadas al modelo)
const s = $input.first().json
const sim = s.simulacro && s.simulacro.respuesta
if (sim === undefined || sim === null) throw new Error('CADENA_SIMULACRO_AGOTADO · el ensayo no trae respuesta simulada para las fechas')
const body = sim.__fallo ? { success: false, error: String(sim.__fallo), cost_usd: 0 } : { success: true, structured_output: sim, cost_usd: 0 }
return [{ json: { ...s, agente: { statusCode: 200, body } } }]

// ④ ARMAR LA LLAMADA AL AGENTE · contexto del flujo sobre el cuerpo que armó la ruta (workflow ids siempre · dry_run explícito)
const s = $input.first().json
const llamada = { ...s.run_sdk, workflow_id: s.workflow_id, workflow_execution_id: s.workflow_execution_id, force_restart: true, dry_run: s.seco === true }
return [{ json: { ...s, llamada } }]

// ⑤ ARMAR `guardar` · el resultado del agente tal cual + las páginas: el CÓDIGO comprueba cada cita contra el texto descargado
const entrada = $input.first().json || {}
const simulado = !!(entrada.agente && entrada.paso)
const s = simulado ? entrada : $('④ Armar la llamada').last().json
const resp = simulado ? entrada.agente : entrada
const b = resp.body && typeof resp.body === 'object' ? resp.body : {}
const ok = Number(resp.statusCode) === 200 && b.success === true
const resultado = ok
  ? { success: true, structured_output: b.structured_output, cost_usd: typeof b.cost_usd === 'number' ? b.cost_usd : null }
  : { success: false, error: String(b.error || b.detail || ('HTTP ' + resp.statusCode)).slice(0, 400), cost_usd: typeof b.cost_usd === 'number' ? b.cost_usd : null }
const paginas = $('③ Armar preparar').last().json.paginas || []
const guardar = { accion: 'guardar', campana_id: s.campana_id, seco: s.seco, corrida_id: s.corrida_id, pais: s.pais, tipo: s.tipo, ambito: s.ambito, anio: s.anio, paginas, resultado, workflow_id: s.workflow_id, workflow_execution_id: s.workflow_execution_id }
return [{ json: { ...s, guardar } }]

// ⑥ SALIDA · lo que el sub-flujo de fechas le devuelve a la puerta (una fecha sin fuente NUNCA detiene la campaña: solo deja pendientes las FILAS que dependen de ella)
// Llega por dos caminos: el FIN temprano (ya verificada / sin fuente: un ítem con `resultado`) o la respuesta de `guardar` (fullResponse).
const e = $input.first().json || {}
const esRespuesta = e.statusCode !== undefined && e.body !== undefined
const b = esRespuesta ? (e.body && typeof e.body === 'object' ? e.body : {}) : (e.detalle && typeof e.detalle === 'object' ? e.detalle : {})
if (esRespuesta && Number(e.statusCode) >= 400) throw new Error('CADENA_FECHAS_GUARDAR_' + String(b.code || b.error || e.statusCode) + ' · ' + String(b.detalle || b.detail || 'sin detalle'))
const entrada = $('⓪ Entrada').last().json
return [{ json: { paso: 'fechas', campana_id: entrada.campana_id, tipo: entrada.tipo, resultado: esRespuesta ? (b.estado || 'ok') : (e.resultado || 'ok'), verificadas: b.verificadas ?? 0, descartadas: b.descartadas || [] } }]
